    increase = vars["v1"] - vars["v2"]
    return {
        "value": increase,
        "trace": {
            "new_value_2019": vars["v1"],
            "old_value_2018": vars["v2"],
            "increase": increase,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
